// Undirected simple weighted graph with BigInt node labels and Number weights.
// Adjacency stored as Map<BigInt, Map<BigInt, Number>> to preserve insertion order.

export class Graph {
  constructor() {
    this._adj = new Map();
    this._edgeCount = 0;
  }

  addWeightedEdge(u, v, weight) {
    if (!this._adj.has(u)) this._adj.set(u, new Map());
    if (!this._adj.has(v)) this._adj.set(v, new Map());
    const nbrsU = this._adj.get(u);
    if (!nbrsU.has(v)) {
      // New edge: record in both directions (once for self-loop).
      nbrsU.set(v, weight);
      if (u !== v) this._adj.get(v).set(u, weight);
      this._edgeCount += 1;
    } else {
      // Unordered duplicate: update weight in place, keep insertion order.
      nbrsU.set(v, weight);
      if (u !== v) this._adj.get(v).set(u, weight);
    }
  }

  numberOfEdges() {
    return this._edgeCount;
  }

  getWeight(u, v) {
    const nbrs = this._adj.get(u);
    if (nbrs === undefined) return undefined;
    return nbrs.get(v);
  }

  *nodes() {
    yield* this._adj.keys();
  }

  *neighbors(node) {
    const nbrs = this._adj.get(node);
    if (nbrs === undefined) return;
    yield* nbrs.keys();
  }

  degree(node) {
    const nbrs = this._adj.get(node);
    if (nbrs === undefined) return 0;
    let deg = 0;
    for (const nbr of nbrs.keys()) {
      deg += nbr === node ? 2 : 1;
    }
    return deg;
  }

  edgeList() {
    const edges = [];
    const seen = new Set();
    for (const [u, nbrs] of this._adj) {
      for (const [v, weight] of nbrs) {
        if (u === v || !seen.has(v)) {
          edges.push({ u, v, weight });
        }
      }
      seen.add(u);
    }
    return edges;
  }
}

export function buildGraph(args) {
  const g = new Graph();
  g.addWeightedEdge(args.a, args.b, 1);
  g.addWeightedEdge(args.b, args.c, 2);
  g.addWeightedEdge(args.c, args.d, 3);
  g.addWeightedEdge(args.d, args.e, 4);
  g.addWeightedEdge(args.a, args.e, 5);
  return g;
}

