// Traversal algorithms: networkx-compatible bfs_edges / dfs_edges.
// Pure JavaScript, ESM, no external modules. Node labels are BigInt.

// networkx bfs_edges: breadth-first over neighbors in adjacency insertion
// order, marking nodes as visited at enqueue time.
export function bfsEdges(graph, source) {
  const edges = [];
  const visited = new Set([source]);
  const queue = [source];
  let head = 0;
  while (head < queue.length) {
    const u = queue[head++];
    for (const v of graph.neighbors(u)) {
      if (!visited.has(v)) {
        visited.add(v);
        queue.push(v);
        edges.push([u, v]);
      }
    }
  }
  return edges;
}

// networkx dfs_edges: iterative stack of resumable neighbor iterators.
// Each stack entry is [parent, iterator]; children are explored depth-first
// in adjacency insertion order (no reversal of neighbors).
export function dfsEdges(graph, source) {
  const edges = [];
  const visited = new Set([source]);
  const stack = [[source, graph.neighbors(source)[Symbol.iterator]()]];
  while (stack.length > 0) {
    const top = stack[stack.length - 1];
    const parent = top[0];
    const step = top[1].next();
    if (step.done) {
      stack.pop();
      continue;
    }
    const child = step.value;
    if (!visited.has(child)) {
      visited.add(child);
      edges.push([parent, child]);
      stack.push([child, graph.neighbors(child)[Symbol.iterator]()]);
    }
  }
  return edges;
}

