// Dijkstra shortest path matching NetworkX semantics.
// Node labels are BigInt; weights/distances are Number.
// Strict-less relaxation only; equal-distance ties are broken by a
// discovery counter so the first-discovered shortest path wins.

class MinHeap {
  constructor() {
    this.items = []; // entries: {dist, count, node}
  }

  less(a, b) {
    if (a.dist !== b.dist) return a.dist < b.dist;
    return a.count < b.count;
  }

  push(entry) {
    const items = this.items;
    items.push(entry);
    let i = items.length - 1;
    while (i > 0) {
      const parent = (i - 1) >> 1;
      if (this.less(items[i], items[parent])) {
        [items[i], items[parent]] = [items[parent], items[i]];
        i = parent;
      } else {
        break;
      }
    }
  }

  pop() {
    const items = this.items;
    const top = items[0];
    const last = items.pop();
    if (items.length > 0) {
      items[0] = last;
      let i = 0;
      const n = items.length;
      for (;;) {
        const left = 2 * i + 1;
        const right = left + 1;
        let smallest = i;
        if (left < n && this.less(items[left], items[smallest])) smallest = left;
        if (right < n && this.less(items[right], items[smallest])) smallest = right;
        if (smallest === i) break;
        [items[i], items[smallest]] = [items[smallest], items[i]];
        i = smallest;
      }
    }
    return top;
  }

  get size() {
    return this.items.length;
  }
}

export function dijkstraPath(graph, source, target) {
  if (source === target) {
    return { length: 0, path: [source], zeroInteger: true };
  }

  const dist = new Map(); // settled node -> final distance
  const seen = new Map(); // discovered node -> best known distance
  const pred = new Map(); // node -> predecessor on shortest path
  const heap = new MinHeap();
  let count = 0;

  seen.set(source, 0);
  heap.push({ dist: 0, count: count++, node: source });

  while (heap.size > 0) {
    const { dist: d, node: u } = heap.pop();
    if (dist.has(u)) continue;
    dist.set(u, d);
    if (u === target) break;

    for (const v of graph.neighbors(u)) {
      const w = graph.getWeight(u, v);
      const vuDist = d + w;
      if (dist.has(v)) {
        if (vuDist < dist.get(v)) {
          throw new Error('Dijkstra: negative weights are not supported');
        }
      } else if (!seen.has(v) || vuDist < seen.get(v)) {
        seen.set(v, vuDist);
        pred.set(v, u);
        heap.push({ dist: vuDist, count: count++, node: v });
      }
    }
  }

  if (!dist.has(target)) {
    throw new Error(`No path between ${String(source)} and ${String(target)}`);
  }

  const path = [target];
  while (path[path.length - 1] !== source) {
    path.push(pred.get(path[path.length - 1]));
  }
  path.reverse();

  return { length: dist.get(target), path, zeroInteger: false };
}

