// Python-style formatting helpers (no imports).

export function formatBool(v) {
  return v ? 'True' : 'False';
}

export function formatFloat(x) {
  if (Number.isInteger(x)) return `${x}.0`;
  return String(x);
}

export function formatPathLength(result) {
  return result.zeroInteger ? '0' : formatFloat(result.length);
}

export function formatNodeList(nodes) {
  return `[${nodes.map((n) => String(n)).join(', ')}]`;
}

export function formatEdgeList(edges) {
  return `[${edges.map(([u, v]) => `(${String(u)}, ${String(v)})`).join(', ')}]`;
}

