node --input-type=module -e "
import { dijkstraPath } from '/output/lib/algorithms/dijkstra.mjs';
class G {
  constructor(){this.adj=new Map();this.w=new Map();}
  add(u,v,wt){const k=a=>String(a);if(!this.adj.has(u))this.adj.set(u,[]);if(!this.adj.has(v))this.adj.set(v,[]);if(!this.adj.get(u).includes(v))this.adj.get(u).push(v);if(u!==v&&!this.adj.get(v).includes(u))this.adj.get(v).push(u);this.w.set(k(u)+'|'+k(v),wt);this.w.set(k(v)+'|'+k(u),wt);}
  neighbors(n){return this.adj.get(n)||[];}
  getWeight(u,v){return this.w.get(String(u)+'|'+String(v));}
}
// buildGraph: (a,b,1),(b,c,2),(c,d,3),(d,e,4),(a,e,5)
const g=new G();
g.add(1n,2n,1);g.add(2n,3n,2);g.add(3n,4n,3);g.add(4n,5n,4);g.add(1n,5n,5);
console.log('a->e', JSON.stringify(dijkstraPath(g,1n,5n),(k,v)=>typeof v==='bigint'?String(v):v));
console.log('a->d', JSON.stringify(dijkstraPath(g,1n,4n),(k,v)=>typeof v==='bigint'?String(v):v));
console.log('same ', JSON.stringify(dijkstraPath(g,3n,3n),(k,v)=>typeof v==='bigint'?String(v):v));
// tie: a->b 1, a->c 1, b->d 1, c->d 1 : both paths length 2; first-discovered (via b, adjacency order) wins
const t=new G();t.add(1n,2n,1);t.add(1n,3n,1);t.add(2n,4n,1);t.add(3n,4n,1);
console.log('tie  ', JSON.stringify(dijkstraPath(t,1n,4n),(k,v)=>typeof v==='bigint'?String(v):v));
// strict-less: equal later discovery must not overwrite pred
const s=new G();s.add(1n,3n,2);s.add(1n,2n,1);s.add(2n,3n,1);
console.log('later', JSON.stringify(dijkstraPath(s,1n,3n),(k,v)=>typeof v==='bigint'?String(v):v));
// unreachable throws
const u=new G();u.add(1n,2n,1);u.add(3n,4n,1);
try{dijkstraPath(u,1n,4n);console.log('FAIL no throw');}catch(e){console.log('unreachable -> throw OK');}
"

