// Node connectivity for the constrained quotient-of-cycle graph.
// Contract:
//   - disconnected graph -> 0
//   - connected graph -> minimum NetworkX degree (self-loop contributes 2)
//   - a single node returns its own degree (self-loop => 2)

export function nodeConnectivity(graph) {
  const nodes = [...graph.nodes()];
  const n = nodes.length;
  if (n === 0) return 0;
  if (n === 1) return graph.degree(nodes[0]);

  // Connectivity check: BFS from the first node using adjacency iterators.
  const visited = new Set([nodes[0]]);
  const queue = [nodes[0]];
  for (let head = 0; head < queue.length; head++) {
    for (const neighbor of graph.neighbors(queue[head])) {
      if (!visited.has(neighbor)) {
        visited.add(neighbor);
        queue.push(neighbor);
      }
    }
  }
  if (visited.size < n) return 0;

  // Connected: node connectivity equals the minimum degree.
  // graph.degree already counts a self-loop twice, matching NetworkX.
  let minDegree = Infinity;
  for (const node of nodes) {
    const d = graph.degree(node);
    if (d < minDegree) minDegree = d;
  }
  return minDegree;
}

