// argparse-compatible CLI parsing (no imports).

const FLAGS = ['--a', '--b', '--c', '--d', '--e'];

function usageLine(prog) {
  return `usage: ${prog} [-h] --a A --b B --c C --d D --e E\n`;
}

function helpText(prog) {
  return (
    usageLine(prog) +
    '\n' +
    'options:\n' +
    '  -h, --help  show this help message and exit\n' +
    '  --a A\n' +
    '  --b B\n' +
    '  --c C\n' +
    '  --d D\n' +
    '  --e E\n'
  );
}

function errorText(prog, message) {
  return usageLine(prog) + `${prog}: error: ${message}\n`;
}

// Python int() semantics: surrounding whitespace stripped, optional sign,
// digits with single underscores allowed only between digits.
function parsePythonInt(raw) {
  const s = raw.replace(/^[ \t\n\r\f\v]+|[ \t\n\r\f\v]+$/g, '');
  if (!/^[+-]?\d(_?\d)*$/.test(s)) return null;
  return BigInt(s.replace(/_/g, ''));
}

// argparse treats a token starting with '-' as an option string unless it
// looks like a negative number (no option strings look like negative numbers).
function looksLikeOption(token) {
  return token.startsWith('-') && !/^-\d+$|^-\d*\.\d+$/.test(token);
}

export function parseCli(argv, prog) {
  const values = new Map();
  const extras = [];

  for (let i = 0; i < argv.length; i++) {
    const token = argv[i];

    if (token === '-h' || token === '--help') {
      return { kind: 'help', text: helpText(prog) };
    }

    let flag = null;
    let raw = null;
    if (token.startsWith('--')) {
      const eq = token.indexOf('=');
      if (eq !== -1) {
        const name = token.slice(0, eq);
        if (FLAGS.includes(name)) {
          flag = name;
          raw = token.slice(eq + 1);
        }
      } else if (FLAGS.includes(token)) {
        flag = token;
        if (i + 1 >= argv.length || looksLikeOption(argv[i + 1])) {
          return {
            kind: 'error',
            text: errorText(prog, `argument ${flag}: expected one argument`),
          };
        }
        raw = argv[++i];
      }
    }

    if (flag === null) {
      extras.push(token);
      continue;
    }

    const value = parsePythonInt(raw);
    if (value === null) {
      return {
        kind: 'error',
        text: errorText(prog, `argument ${flag}: invalid int value: '${raw}'`),
      };
    }
    values.set(flag, value); // duplicates: last wins
  }

  const missing = FLAGS.filter((f) => !values.has(f));
  if (missing.length > 0) {
    return {
      kind: 'error',
      text: errorText(
        prog,
        `the following arguments are required: ${missing.join(', ')}`
      ),
    };
  }

  if (extras.length > 0) {
    return {
      kind: 'error',
      text: errorText(prog, `unrecognized arguments: ${extras.join(' ')}`),
    };
  }

  return {
    kind: 'ok',
    args: {
      a: values.get('--a'),
      b: values.get('--b'),
      c: values.get('--c'),
      d: values.get('--d'),
      e: values.get('--e'),
    },
  };
}

