46	  const edges = [];
47	  const members = new Map();
48	
49	  function addMembership(u, v) {
50	    if (!members.has(u)) members.set(u, new Set());
51	    members.get(u).add(v);
52	  }
53	
54	  for (const { edge } of sortedEdges) {
55	    // NetworkX Kruskal ignores self-loops when constructing the MST.
56	    if (edge.u === edge.v) continue;
57	    if (union(edge.u, edge.v)) {
58	      edges.push({ u: edge.u, v: edge.v, weight: edge.weight });
59	      addMembership(edge.u, edge.v);
60	      addMembership(edge.v, edge.u);
61	    }
62	  }
63	
64	  return {
65	    edges,
66	    edgeCount: edges.length,
67	    hasEdge(u, v) {
68	      const neighbors = members.get(u);
69	      return neighbors !== undefined && neighbors.has(v);
70	    },
71	  };
72	}

1	// Dijkstra shortest path matching NetworkX semantics.
2	// Node labels are BigInt; weights/distances are Number.
3	// Strict-less relaxation only; equal-distance ties are broken by a
4	// discovery counter so the first-discovered shortest path wins.
5	
6	class MinHeap {
7	  constructor() {
8	    this.items = []; // entries: {dist, count, node}
9	  }
10	
11	  less(a, b) {
12	    if (a.dist !== b.dist) return a.dist < b.dist;
13	    return a.count < b.count;
14	  }
15	
16	  push(entry) {
17	    const items = this.items;
18	    items.push(entry);
19	    let i = items.length - 1;
20	    while (i > 0) {
21	      const parent = (i - 1) >> 1;
22	      if (this.less(items[i], items[parent])) {
23	        [items[i], items[parent]] = [items[parent], items[i]];
24	        i = parent;
25	      } else {
26	        break;
27	      }
28	    }
29	  }
30	
31	  pop() {
32	    const items = this.items;
33	    const top = items[0];
34	    const last = items.pop();
35	    if (items.length > 0) {
36	      items[0] = last;
37	      let i = 0;
38	      const n = items.length;
39	      for (;;) {
40	        const left = 2 * i + 1;
41	        const right = left + 1;
42	        let smallest = i;
43	        if (left < n && this.less(items[left], items[smallest])) smallest = left;
44	        if (right < n && this.less(items[right], items[smallest])) smallest = right;
45	        if (smallest === i) break;
46	        [items[i], items[smallest]] = [items[smallest], items[i]];
47	        i = smallest;
48	      }
49	    }
50	    return top;
51	  }
52	
53	  get size() {
54	    return this.items.length;
55	  }
56	}
57	
58	export function dijkstraPath(graph, source, target) {
59	  if (source === target) {
60	    return { length: 0, path: [source], zeroInteger: true };
61	  }
62	
63	  const dist = new Map(); // settled node -> final distance
64	  const seen = new Map(); // discovered node -> best known distance
65	  const pred = new Map(); // node -> predecessor on shortest path
66	  const heap = new MinHeap();
67	  let count = 0;
68	
69	  seen.set(source, 0);
70	  heap.push({ dist: 0, count: count++, node: source });
71	
72	  while (heap.size > 0) {
73	    const { dist: d, node: u } = heap.pop();
74	    if (dist.has(u)) continue;
75	    dist.set(u, d);
76	    if (u === target) break;
77	
78	    for (const v of graph.neighbors(u)) {
79	      const w = graph.getWeight(u, v);
80	      const vuDist = d + w;
81	      if (dist.has(v)) {
82	        if (vuDist < dist.get(v)) {
83	          throw new Error('Dijkstra: negative weights are not supported');
84	        }
85	      } else if (!seen.has(v) || vuDist < seen.get(v)) {
86	        seen.set(v, vuDist);
87	        pred.set(v, u);
88	        heap.push({ dist: vuDist, count: count++, node: v });
89	      }
90	    }
91	  }
92	
93	  if (!dist.has(target)) {
94	    throw new Error(`No path between ${String(source)} and ${String(target)}`);
95	  }
96	
97	  const path = [target];
98	  while (path[path.length - 1] !== source) {
99	    path.push(pred.get(path[path.length - 1]));
100	  }
101	  path.reverse();
102	
103	  return { length: dist.get(target), path, zeroInteger: false };
104	}

1	// Traversal algorithms: networkx-compatible bfs_edges / dfs_edges.
2	// Pure JavaScript, ESM, no external modules. Node labels are BigInt.
3	
4	// networkx bfs_edges: breadth-first over neighbors in adjacency insertion
5	// order, marking nodes as visited at enqueue time.
6	export function bfsEdges(graph, source) {
7	  const edges = [];
8	  const visited = new Set([source]);
9	  const queue = [source];
10	  let head = 0;
11	  while (head < queue.length) {
12	    const u = queue[head++];
13	    for (const v of graph.neighbors(u)) {
14	      if (!visited.has(v)) {
15	        visited.add(v);
16	        queue.push(v);
17	        edges.push([u, v]);
18	      }
19	    }
20	  }
21	  return edges;
22	}
23	
24	// networkx dfs_edges: iterative stack of resumable neighbor iterators.
25	// Each stack entry is [parent, iterator]; children are explored depth-first
26	// in adjacency insertion order (no reversal of neighbors).
27	export function dfsEdges(graph, source) {
28	  const edges = [];
29	  const visited = new Set([source]);
30	  const stack = [[source, graph.neighbors(source)[Symbol.iterator]()]];
31	  while (stack.length > 0) {
32	    const top = stack[stack.length - 1];
33	    const parent = top[0];
34	    const step = top[1].next();
35	    if (step.done) {
36	      stack.pop();
37	      continue;
38	    }
39	    const child = step.value;
40	    if (!visited.has(child)) {
41	      visited.add(child);
42	      edges.push([parent, child]);
43	      stack.push([child, graph.neighbors(child)[Symbol.iterator]()]);
44	    }
45	  }
46	  return edges;
47	}

1	// Node connectivity for the constrained quotient-of-cycle graph.
2	// Contract:
3	//   - disconnected graph -> 0
4	//   - connected graph -> minimum NetworkX degree (self-loop contributes 2)
5	//   - a single node returns its own degree (self-loop => 2)
6	
7	export function nodeConnectivity(graph) {
8	  const nodes = [...graph.nodes()];
9	  const n = nodes.length;
10	  if (n === 0) return 0;
11	  if (n === 1) return graph.degree(nodes[0]);
12	
13	  // Connectivity check: BFS from the first node using adjacency iterators.
14	  const visited = new Set([nodes[0]]);
15	  const queue = [nodes[0]];
16	  for (let head = 0; head < queue.length; head++) {
17	    for (const neighbor of graph.neighbors(queue[head])) {
18	      if (!visited.has(neighbor)) {
19	        visited.add(neighbor);
20	        queue.push(neighbor);
21	      }
22	    }
23	  }
24	  if (visited.size < n) return 0;
25	
26	  // Connected: node connectivity equals the minimum degree.
27	  // graph.degree already counts a self-loop twice, matching NetworkX.
28	  let minDegree = Infinity;
29	  for (const node of nodes) {
30	    const d = graph.degree(node);
31	    if (d < minDegree) minDegree = d;
32	  }
33	  return minDegree;
34	}

1	// Python-style formatting helpers (no imports).
2	
3	export function formatBool(v) {
4	  return v ? 'True' : 'False';
5	}
6	
7	export function formatFloat(x) {
8	  if (Number.isInteger(x)) return `${x}.0`;
9	  return String(x);
10	}
11	
12	export function formatPathLength(result) {
13	  return result.zeroInteger ? '0' : formatFloat(result.length);
14	}
15	
16	export function formatNodeList(nodes) {
17	  return `[${nodes.map((n) => String(n)).join(', ')}]`;
18	}
19	
20	export function formatEdgeList(edges) {
21	  return `[${edges.map(([u, v]) => `(${String(u)}, ${String(v)})`).join(', ')}]`;
22	}

1	// argparse-compatible CLI parsing (no imports).
2	
3	const FLAGS = ['--a', '--b', '--c', '--d', '--e'];
4	
5	function usageLine(prog) {
6	  return `usage: ${prog} [-h] --a A --b B --c C --d D --e E\n`;
7	}
8	
9	function helpText(prog) {
10	  return (
11	    usageLine(prog) +
12	    '\n' +
13	    'options:\n' +
14	    '  -h, --help  show this help message and exit\n' +
15	    '  --a A\n' +
16	    '  --b B\n' +
17	    '  --c C\n' +
18	    '  --d D\n' +
19	    '  --e E\n'
20	  );
21	}
22	
23	function errorText(prog, message) {
24	  return usageLine(prog) + `${prog}: error: ${message}\n`;
25	}
26	
27	// Python int() semantics: surrounding whitespace stripped, optional sign,
28	// digits with single underscores allowed only between digits.
29	function parsePythonInt(raw) {
30	  const s = raw.replace(/^[ \t\n\r\f\v]+|[ \t\n\r\f\v]+$/g, '');
31	  if (!/^[+-]?\d(_?\d)*$/.test(s)) return null;
32	  return BigInt(s.replace(/_/g, ''));
33	}
34	
35	// argparse treats a token starting with '-' as an option string unless it
36	// looks like a negative number (no option strings look like negative numbers).
37	function looksLikeOption(token) {
38	  return token.startsWith('-') && !/^-\d+$|^-\d*\.\d+$/.test(token);
39	}
40	
41	export function parseCli(argv, prog) {
42	  const values = new Map();
43	  const extras = [];
44	
45	  for (let i = 0; i < argv.length; i++) {
46	    const token = argv[i];
47	
48	    if (token === '-h' || token === '--help') {
49	      return { kind: 'help', text: helpText(prog) };
50	    }
51	
52	    let flag = null;
53	    let raw = null;
54	    if (token.startsWith('--')) {
55	      const eq = token.indexOf('=');
56	      if (eq !== -1) {
57	        const name = token.slice(0, eq);
58	        if (FLAGS.includes(name)) {
59	          flag = name;
60	          raw = token.slice(eq + 1);
61	        }
62	      } else if (FLAGS.includes(token)) {
63	        flag = token;
64	        if (i + 1 >= argv.length || looksLikeOption(argv[i + 1])) {
65	          return {
66	            kind: 'error',
67	            text: errorText(prog, `argument ${flag}: expected one argument`),
68	          };
69	        }
70	        raw = argv[++i];
71	      }
72	    }
73	
74	    if (flag === null) {
75	      extras.push(token);
76	      continue;
77	    }
78	
79	    const value = parsePythonInt(raw);
80	    if (value === null) {
81	      return {
82	        kind: 'error',
83	        text: errorText(prog, `argument ${flag}: invalid int value: '${raw}'`),
84	      };
85	    }
86	    values.set(flag, value); // duplicates: last wins
87	  }
88	
89	  const missing = FLAGS.filter((f) => !values.has(f));
90	  if (missing.length > 0) {
91	    return {
92	      kind: 'error',
93	      text: errorText(
94	        prog,
95	        `the following arguments are required: ${missing.join(', ')}`
96	      ),
97	    };
98	  }
99	
100	  if (extras.length > 0) {
101	    return {
102	      kind: 'error',
103	      text: errorText(prog, `unrecognized arguments: ${extras.join(' ')}`),
104	    };
105	  }
106	
107	  return {
108	    kind: 'ok',
109	    args: {
110	      a: values.get('--a'),
111	      b: values.get('--b'),
112	      c: values.get('--c'),
113	      d: values.get('--d'),
114	      e: values.get('--e'),
115	    },
116	  };
117	}

